-- Check: sample records per register (10 each).
SELECT l.register_key, count(r.id) AS records
FROM public.local_registers l
LEFT JOIN public.local_register_records r ON r.register_id = l.id AND r.is_deleted = FALSE
WHERE l.id IN ('00000000-0000-4000-900a-00000000000d'::uuid, '00000000-0000-4000-900a-00000000000e'::uuid, '00000000-0000-4000-900a-00000000000f'::uuid, '00000000-0000-4000-900a-000000000010'::uuid, '00000000-0000-4000-900a-000000000011'::uuid, '00000000-0000-4000-900a-000000000012'::uuid)
GROUP BY l.register_key ORDER BY l.register_key;
